const d=new IntersectionObserver(e=>e.forEach(n=>{n.isIntersecting&&n.target.classList.add("in-view")}),{threshold:.1,rootMargin:"0px 0px -40px 0px"});document.querySelectorAll(".reveal").forEach(e=>d.observe(e));const c=document.querySelector(".nav-header");window.addEventListener("scroll",()=>{c?.classList.toggle("scrolled",window.scrollY>50)},{passive:!0});const l=document.getElementById("mob-toggle"),t=document.getElementById("mob-menu"),s=document.getElementById("ham-open"),o=document.getElementById("ham-close");l?.addEventListener("click",()=>{const e=t?.classList.toggle("hidden");s?.classList.toggle("hidden",!e),o?.classList.toggle("hidden",!!e)});t?.querySelectorAll(".mob-link, .btn-primary").forEach(e=>{e.addEventListener("click",()=>{t.classList.add("hidden"),s?.classList.remove("hidden"),o?.classList.add("hidden")})});
